// spec: .qa/e2e/specs/prayer-history.md
// seed: tests/seed.user1.spec.ts
// NOTE: шаги с page.route (route.fetch + fulfill) в живом браузере не проверялись (недоступно в MCP); шаг 1 (чтение истории) проверен вживую на 1440.
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('История молитв', () => {
  test('PH-02 Две записи одной молитвы в одну минуту — с секундами (история и «תפילות אחרונות») #6a86f7e9 @prod-safe @mobile', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. Открыть `/journey/history` → группа «י״ב תשרי · 23 בספט׳».
    await page.goto('/journey/history');
    const group = page.getByRole('heading', { level: 1, name: 'י״ב תשרי · 23 בספט׳' });
    await expect(group).toBeVisible({ timeout: 20_000 });
    // Одиночная в минуте запись — HH:mm; серия в одну минуту — HH:mm:ss.
    await expect(page.getByRole('region', { name: 'מנחה, י״ב תשרי · 23 בספט׳, 15:12' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'מנחה, י״ב תשרי · 23 בספט׳, 15:11:14' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'מנחה, י״ב תשרי · 23 בספט׳, 15:11:12' })).toBeVisible();

    // 2. До перехода: подмена ответа — реальный ответ + копия первой записи на 3 с раньше.
    let injectedTime = '';
    await page.route('**/rest/v1/prayer_completions**', async (route) => {
      if (route.request().method() !== 'GET') return route.continue();
      const response = await route.fetch();
      let body: any;
      try {
        body = await response.json();
      } catch {
        return route.fulfill({ response });
      }
      if (!Array.isArray(body) || body.length === 0) return route.fulfill({ response, json: body });
      const first = body[0];
      const timeKey =
        ['completed_at', 'finished_at', 'created_at'].find((k) => typeof first[k] === 'string') ??
        Object.keys(first).find((k) => typeof first[k] === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(first[k]));
      if (!timeKey) return route.fulfill({ response, json: body });
      const copy = { ...first };
      copy[timeKey] = new Date(new Date(first[timeKey]).getTime() - 3000).toISOString();
      if ('id' in copy) copy.id = typeof copy.id === 'number' ? copy.id + 1_000_000 : `${copy.id}-qa-copy`;
      injectedTime = copy[timeKey];
      // Копия вставляется сразу за первой записью (порядок: новее → старее).
      return route.fulfill({ response, json: [first, copy, ...body.slice(1)] });
    });

    // 3. Открыть `/home` → блок «תפילות אחרונות».
    await page.goto('/home');
    await expect(page.getByText('תפילות אחרונות', { exact: true })).toBeVisible({ timeout: 20_000 });
    const recent = page.getByText(/^[א-ת״׳' ]+ · \d{2}:\d{2}:\d{2}$/);
    await expect(recent).toHaveCount(2);
    const secs = (await recent.allInnerTexts()).map((t) => Number(t.split(':').pop()));
    const diff = (secs[0] - secs[1] + 60) % 60;
    expect(diff).toBe(3);

    // 4. Открыть `/journey/history` (подмена активна) — те же две записи с HH:mm:ss.
    await page.goto('/journey/history');
    await expect(page.getByRole('heading', { level: 1 }).first()).toBeVisible({ timeout: 20_000 });
    const firstTwo = page.getByRole('region', { name: /, \d{2}:\d{2}(:\d{2})?$/ });
    const names = await firstTwo.evaluateAll((els) => els.slice(0, 2).map((e) => e.getAttribute('aria-label') || ''));
    expect(names).toHaveLength(2);
    for (const n of names) expect(n).toMatch(/, \d{2}:\d{2}:\d{2}$/);
    expect(injectedTime).not.toBe('');
  });
});
